{"code": "import pandas as pd

df = pd.read_excel("DuLieuBanHang.xlsx", sheet_name="DanhSachHoaDon", usecols=["Mã hóa đơn","Thời gian","Trạng thái"])
detail = pd.read_excel("DanhSachHoaDonChiTiet.xlsx", sheet_name="Sheet1", usecols=["Mã hóa đơn","Thành tiền"])

# Parse date column: mix of serial ints and dd/mm/yyyy strings
def parse_date(v):
    if isinstance(v, (int, float)):
        from datetime import datetime, timedelta
        return datetime(1899,12,30) + timedelta(days=int(v))
    s = str(v).strip()
    if not s:
        return pd.NaT
    for fmt in ("%d/%m/%Y","%Y-%m-%d"):
        try:
            return pd.to_datetime(s, format=fmt)
        except Exception:
            pass
    return pd.to_datetime(s, errors="coerce")

df["d"] = df["Thời gian"].apply(parse_date)

# Revenue: exclude cancelled and returned orders
cancel_return = {"hủy đơn","Đã huỷ","trả hàng","Đã trả hàng"}
df["revenue"] = False
df.loc[~df["Trạng thái"].astype(str).str.lower().isin(cancel_return), "revenue"] = True

# Join detail
m = df.merge(detail, on="Mã hóa đơn", how="left")
m["line_rev"] = pd.to_numeric(m["Thành tiền"], errors="coerce").fillna(0)
m["order_rev"] = m["line_rev"].groupby(m["Mã hóa đơn"]).transform("sum")

for mon in ["2025-07","2025-08","2025-09"]:
    sub = m[(m["d"].dt.to_period("M")==pd.Period(mon)) & m["revenue"]]
    print(mon, "revenue=", int(sub["order_rev"].sum()), "orders=", sub["Mã hóa đơn"].nunique())
"}

